using Amazon.DynamoDBv2.DataModel;
using CSharpFunctionalExtensions;
using Microsoft.Extensions.Logging;
using VibraHeka.Domain.Recordings.Entities;
using VibraHeka.Domain.Recordings.Ports.Out;
using VibraHeka.Infrastructure.Entities;
using VibraHeka.Infrastructure.Mappers;
using VibraHeka.Infrastructure.Persistence.DynamoDB.Models;

namespace VibraHeka.Infrastructure.Persistence.Repository;

public class RecordingRepository(
    IDynamoDBContext context,
    AWSConfig config,
    RecordingEntityMapper mapper,
    ILogger<RecordingRepository> logger)
    : GenericDynamoRepository<RecordingDBModel>(context, config.RecordingsTable, logger),
        IRecordingRegistryPort
{
    public Task<Result<string>> SaveRecording(RecordingEntity recording, CancellationToken cancellationToken)
    {
        return Save(mapper.FromDomain(recording), cancellationToken).Map(_ => recording.Id);
    }

    public async Task<Result<IEnumerable<RecordingEntity>>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await GetAll(cancellationToken).Map(models => models.Select(mapper.FromDbModel));
    }
}

using Amazon.DynamoDBv2.DataModel;
using CSharpFunctionalExtensions;
using Microsoft.Extensions.Logging;
using VibraHeka.Domain.Recordings.Entities;
using VibraHeka.Domain.Recordings.Errors;
using VibraHeka.Domain.Recordings.Ports.Out;
using VibraHeka.Infrastructure.Entities;
using VibraHeka.Infrastructure.Exceptions;
using VibraHeka.Infrastructure.Mappers;
using VibraHeka.Infrastructure.Persistence.DynamoDB.Models;

namespace VibraHeka.Infrastructure.Persistence.Repository;

public class RecordingRepository(
    IDynamoDBContext context,
    AWSConfig config,
    RecordingEntityMapper mapper,
    ILogger<RecordingRepository> logger)
    : GenericDynamoRepository<RecordingDBModel>(context, config.RecordingsTable, logger),
        IRecordingRegistryPort
{
    public Task<Result<string>> SaveRecording(RecordingEntity recording, CancellationToken cancellationToken)
    {
        return Save(mapper.FromDomain(recording), cancellationToken).Map(_ => recording.Id);
    }

    public async Task<Result<IEnumerable<RecordingEntity>>> GetAllAsync(CancellationToken cancellationToken)
    {
        return await GetAll(cancellationToken).Map(models => models.Select(mapper.FromDbModel));
    }

    public async Task<Result<RecordingEntity>> GetByIdAsync(string recordingId, CancellationToken cancellationToken)
    {
        return await FindByID(recordingId, cancellationToken)
            .MapError(error => error == GenericPersistenceErrors.NoRecordsFound
                ? RecordingErrors.NotFound
                : error)
            .Map(mapper.FromDbModel);
    }
}

using System.Net;
using Amazon.S3;
using Amazon.S3.Model;
using CSharpFunctionalExtensions;
using VibraHeka.Domain.Recordings.Errors;
using VibraHeka.Domain.Recordings.Ports.Out;
using VibraHeka.Infrastructure.Entities;

namespace VibraHeka.Infrastructure.Persistence.S3;

public class RecordingStorageRepository(IAmazonS3 client, AWSConfig options)
    : GenericS3Repository(client, options.RecordingsBucketName), IRecordingStoragePort
{
    public async Task<Result<string>> UploadAsync(
        string recordingId,
        Stream fileStream,
        string fileName,
        CancellationToken cancellationToken)
    {
        string tempPath = Path.Combine(Path.GetTempPath(), fileName);
        FileInfo fileInfo = await StreamToFile(fileStream, tempPath, cancellationToken);

        try
        {
            Result<string> result = await UploadAsync(fileInfo, recordingId, cancellationToken);
            return result;
        }
        finally
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
    }
}

using System.Net;
using Amazon.S3;
using Amazon.S3.Model;
using CSharpFunctionalExtensions;
using VibraHeka.Domain.Recordings.Errors;
using VibraHeka.Domain.Recordings.Ports.Out;
using VibraHeka.Infrastructure.Entities;

namespace VibraHeka.Infrastructure.Persistence.S3;

public class RecordingStorageRepository(IAmazonS3 client, AWSConfig options)
    : GenericS3Repository(client, options.RecordingsBucketName), IRecordingStoragePort
{
    private const int DownloadUrlExpirySeconds = 3600;

    public async Task<Result<string>> UploadAsync(
        string recordingId,
        Stream fileStream,
        string fileName,
        CancellationToken cancellationToken)
    {
        string tempPath = Path.Combine(Path.GetTempPath(), fileName);
        FileInfo fileInfo = await StreamToFile(fileStream, tempPath, cancellationToken);

        try
        {
            Result<string> result = await UploadAsync(fileInfo, recordingId, cancellationToken);
            return result;
        }
        finally
        {
            if (File.Exists(tempPath))
                File.Delete(tempPath);
        }
    }

    public Task<Result<string>> GetDownloadUrlAsync(string storageKey, CancellationToken cancellationToken)
    {
        string s3ObjectKey = ExtractS3Key(storageKey);
        return GetDownloadPreSignedUrl(s3ObjectKey, DownloadUrlExpirySeconds);
    }

    private static string ExtractS3Key(string storageKey)
    {
        if (!Uri.TryCreate(storageKey, UriKind.Absolute, out Uri? uri))
        {
            return storageKey;
        }

        return uri.AbsolutePath.TrimStart('/');
    }
}

using CSharpFunctionalExtensions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using VibraHeka.Application.Recordings.Commnads.AdminAddRecording;
using VibraHeka.Application.Recordings.Queries.GetAllRecordings;
using VibraHeka.Domain.Entities;
using VibraHeka.Web.Entities;

namespace VibraHeka.Web.Controllers;

[ApiController]
[Route("api/v1/recordings")]
public class RecordingController(IMediator mediator)
{
    /// <summary>
    /// Uploads a new video recording. Only administrators can perform this action.
    /// </summary>
    /// <param name="request">The video file to upload request.</param>
    /// <returns>The ID of the newly created recording on success.</returns>
    [HttpPost]
    [Authorize]
    [Consumes("multipart/form-data")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(ResponseEntity), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> UploadRecording(
        [FromForm] UploadRecordingRequest request)
    {

        AdminAddRecordingCommand command = new(
            Name: request.Name,
            Description: request.Description,
            Type: request.Type,
            FileStream: request.File.OpenReadStream(),
            FileName: request.File.FileName);

        Result<string> result = await mediator.Send(command);

        if (result.IsFailure)
        {
            return new BadRequestObjectResult(ResponseEntity.FromError(result.Error));
        }

        return new OkObjectResult(ResponseEntity.FromSuccess(result.Value));
    }

    /// <summary>
    /// Returns all available recordings.
    /// </summary>
    /// <returns>List of recordings.</returns>
    [HttpGet]
    [Authorize]
    [Produces("application/json")]
    [ProducesResponseType(typeof(ResponseEntity), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> GetAllRecordings()
    {
        Result<IEnumerable<RecordingDto>> result = await mediator.Send(new GetAllRecordingsQuery());

        if (result.IsFailure)
        {
            return new BadRequestObjectResult(ResponseEntity.FromError(result.Error));
        }

        return new OkObjectResult(ResponseEntity.FromSuccess(result.Value));
    }
}

using CSharpFunctionalExtensions;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Mvc;
using VibraHeka.Application.Recordings.Commnads.AdminAddRecording;
using VibraHeka.Application.Recordings.Queries.GetAllRecordings;
using VibraHeka.Application.Recordings.Queries.GetRecordingDownloadUrl;
using VibraHeka.Domain.Entities;
using VibraHeka.Domain.Recordings.Errors;
using VibraHeka.Web.Entities;

namespace VibraHeka.Web.Controllers;

[ApiController]
[Route("api/v1/recordings")]
public class RecordingController(IMediator mediator)
{
    /// <summary>
    /// Uploads a new video recording. Only administrators can perform this action.
    /// </summary>
    /// <param name="request">The video file to upload request.</param>
    /// <returns>The ID of the newly created recording on success.</returns>
    [HttpPost]
    [Authorize]
    [Consumes("multipart/form-data")]
    [Produces("application/json")]
    [ProducesResponseType(typeof(ResponseEntity), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> UploadRecording(
        [FromForm] UploadRecordingRequest request)
    {

        AdminAddRecordingCommand command = new(
            Name: request.Name,
            Description: request.Description,
            Type: request.Type,
            FileStream: request.File.OpenReadStream(),
            FileName: request.File.FileName);

        Result<string> result = await mediator.Send(command);

        if (result.IsFailure)
        {
            return new BadRequestObjectResult(ResponseEntity.FromError(result.Error));
        }

        return new OkObjectResult(ResponseEntity.FromSuccess(result.Value));
    }

    /// <summary>
    /// Returns all available recordings.
    /// </summary>
    /// <returns>List of recordings.</returns>
    [HttpGet]
    [Authorize]
    [Produces("application/json")]
    [ProducesResponseType(typeof(ResponseEntity), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    public async Task<IActionResult> GetAllRecordings()
    {
        Result<IEnumerable<RecordingDto>> result = await mediator.Send(new GetAllRecordingsQuery());

        if (result.IsFailure)
        {
            return new BadRequestObjectResult(ResponseEntity.FromError(result.Error));
        }

        return new OkObjectResult(ResponseEntity.FromSuccess(result.Value));
    }

    /// <summary>
    /// Returns a temporary download URL for the specified recording.
    /// </summary>
    /// <param name="recordingId">The unique identifier of the recording.</param>
    /// <param name="ct">Cancellation token.</param>
    /// <returns>A pre-signed download URL valid for a limited time.</returns>
    [HttpGet("{recordingId}/download-url")]
    [Authorize]
    [Produces("application/json")]
    [ProducesResponseType(typeof(ResponseEntity), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status400BadRequest)]
    [ProducesResponseType(StatusCodes.Status401Unauthorized)]
    [ProducesResponseType(StatusCodes.Status404NotFound)]
    public async Task<IActionResult> GetDownloadUrl(string recordingId, CancellationToken ct)
    {
        Result<RecordingDownloadUrlDto> result =
            await mediator.Send(new GetRecordingDownloadUrlQuery(recordingId), ct);

        if (result.IsFailure)
        {
            if (result.Error == RecordingErrors.NotFound)
                return new NotFoundObjectResult(ResponseEntity.FromError(result.Error));

            return new BadRequestObjectResult(ResponseEntity.FromError(result.Error));
        }

        return new OkObjectResult(ResponseEntity.FromSuccess(result.Value));
    }
}

