{
    private Mock<IRecordingStoragePort> StoragePortMock = default!;
    private Mock<IRecordingRegistryPort> RegistryPortMock = default!;
    private Mock<ICurrentUserService> CurrentUserServiceMock = default!;
    private AdminAddRecordingCommandHandler Handler = default!;

    [SetUp]
    public void SetUp()
    {
        StoragePortMock = new Mock<IRecordingStoragePort>();
        RegistryPortMock = new Mock<IRecordingRegistryPort>();
        CurrentUserServiceMock = new Mock<ICurrentUserService>();

        Handler = new AdminAddRecordingCommandHandler(
            StoragePortMock.Object,
            RegistryPortMock.Object,
            CurrentUserServiceMock.Object);
    }

    #region Happy Path Tests

    [Test]
    [DisplayName("Should return success with recording ID when upload and save succeed")]
    public async Task ShouldReturnSuccessWithRecordingIdWhenUploadAndSaveSucceed()
    {
        // Given: a valid command, storage returns a storage key, and registry saves successfully
        Stream fileStream = new MemoryStream(new byte[] { 1, 2, 3 });
        AdminAddRecordingCommand command = new(
            Name: "Meditacion matutina",
            Description: "Una sesion de meditacion para empezar el dia",
            Type: RecordingType.Meditacion,
            FileStream: fileStream,
            FileName: "meditacion.mp4");

        string adminUserId = "admin-user-id";
        string storageKey = "recordings/some-id/meditacion.mp4";

        CurrentUserServiceMock.Setup(x => x.UserId).Returns(adminUserId);

        StoragePortMock
            .Setup(x => x.UploadAsync(It.IsAny<string>(), fileStream, command.FileName, It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success(storageKey));

        RegistryPortMock
            .Setup(x => x.SaveAsync(It.IsAny<RecordingEntity>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync((RecordingEntity entity, CancellationToken _) => Result.Success(entity.Id));

        // When: the handler processes the command
        Result<string> result = await Handler.Handle(command, CancellationToken.None);

        // Then: the result should be success and contain a non-empty recording ID
        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value, Is.Not.Null.And.Not.Empty,
            "Expected a non-empty recording ID but got null or empty");

        StoragePortMock.Verify(
            x => x.UploadAsync(
                It.Is<string>(id => !string.IsNullOrEmpty(id)),
                It.Is<Stream>(s => ReferenceEquals(s, fileStream)),
                It.Is<string>(fn => fn == command.FileName),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected UploadAsync to be called exactly once with the provided stream and fileName");

        RegistryPortMock.Verify(
            x => x.SaveAsync(
                It.Is<RecordingEntity>(e =>
                    e.Name == command.Name &&
                    e.Description == command.Description &&
                    e.Type == command.Type &&
                    e.StorageKey == storageKey &&
                    e.CreatedBy == adminUserId &&
                    !string.IsNullOrEmpty(e.Id)),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected SaveAsync to be called once with entity containing correct Name, Description, Type, StorageKey and CreatedBy");

        StoragePortMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
    }

    #endregion

    #region Railway Pattern Tests

    [Test]
    [DisplayName("Should not call RegistryPort when StoragePort fails (Railway)")]
    public async Task ShouldNotCallRegistryPortWhenStoragePortFails()
    {
        // Given: a valid command but storage upload fails
        Stream fileStream = new MemoryStream(new byte[] { 1, 2, 3 });
        AdminAddRecordingCommand command = new(
            Name: "Masterclass de yoga",
            Description: "Clase completa de yoga para principiantes",
            Type: RecordingType.Masterclass,
            FileStream: fileStream,
            FileName: "yoga.mp4");

        string uploadError = RecordingErrors.UploadFailed;

        CurrentUserServiceMock.Setup(x => x.UserId).Returns("admin-user-id");

        StoragePortMock
            .Setup(x => x.UploadAsync(It.IsAny<string>(), fileStream, command.FileName, It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Failure<string>(uploadError));

        // When: the handler processes the command
        Result<string> result = await Handler.Handle(command, CancellationToken.None);

        // Then: result should be failure and RegistryPort should never be invoked
        Assert.That(result.IsSuccess, Is.False,
            $"Expected failure when StoragePort fails, but got success with value: '{(result.IsSuccess ? result.Value : "N/A")}'");
        Assert.That(result.Error, Is.EqualTo(uploadError),
            $"Expected error '{uploadError}' but got: '{result.Error}'");

        StoragePortMock.Verify(
            x => x.UploadAsync(
                It.Is<string>(id => !string.IsNullOrEmpty(id)),
                It.Is<Stream>(s => ReferenceEquals(s, fileStream)),
                It.Is<string>(fn => fn == command.FileName),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected UploadAsync to be called once even on failure");

        RegistryPortMock.Verify(
            x => x.SaveAsync(
                It.Is<RecordingEntity>(e => e != null),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Never,
            "Expected SaveAsync to never be called when StoragePort fails (Railway pattern)");

        StoragePortMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should return failure when RegistryPort fails after successful upload")]
    public async Task ShouldReturnFailureWhenRegistryPortFails()
    {
        // Given: storage upload succeeds but registry save fails
        Stream fileStream = new MemoryStream(new byte[] { 1, 2, 3 });
        AdminAddRecordingCommand command = new(
            Name: "Taller de respiracion",
            Description: "Tecnicas avanzadas de respiracion consciente",
            Type: RecordingType.Taller,
            FileStream: fileStream,
            FileName: "respiracion.mp4");

        string storageKey = "recordings/some-id/respiracion.mp4";
        string registryError = "REGISTRY_SAVE_FAILED";

        CurrentUserServiceMock.Setup(x => x.UserId).Returns("admin-user-id");

        StoragePortMock
            .Setup(x => x.UploadAsync(It.IsAny<string>(), fileStream, command.FileName, It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success(storageKey));

        RegistryPortMock
            .Setup(x => x.SaveAsync(It.IsAny<RecordingEntity>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Failure<string>(registryError));

        // When: the handler processes the command
        Result<string> result = await Handler.Handle(command, CancellationToken.None);

        // Then: result should be failure with the registry error message
        Assert.That(result.IsSuccess, Is.False,
            $"Expected failure when RegistryPort fails, but got success with value: '{(result.IsSuccess ? result.Value : "N/A")}'");
        Assert.That(result.Error, Is.EqualTo(registryError),
            $"Expected error '{registryError}' but got: '{result.Error}'");

        StoragePortMock.Verify(
            x => x.UploadAsync(
                It.Is<string>(id => !string.IsNullOrEmpty(id)),
                It.Is<Stream>(s => ReferenceEquals(s, fileStream)),
                It.Is<string>(fn => fn == command.FileName),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected UploadAsync to be called once");

        RegistryPortMock.Verify(
            x => x.SaveAsync(
                It.Is<RecordingEntity>(e =>
                    e.Name == command.Name &&
                    e.Description == command.Description &&
                    e.Type == command.Type &&
                    e.StorageKey == storageKey &&
                    !string.IsNullOrEmpty(e.Id)),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected SaveAsync to be called once even when it returns failure");

        StoragePortMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
    }

    #endregion

    #region Entity Mapping Tests

    [Test]
    [DisplayName("Should generate a unique recording ID for each command execution")]
    public async Task ShouldGenerateUniqueRecordingIdForEachExecution()
    {
        // Given: two identical commands
        Stream fileStream1 = new MemoryStream(new byte[] { 1, 2, 3 });
        Stream fileStream2 = new MemoryStream(new byte[] { 4, 5, 6 });
        AdminAddRecordingCommand command1 = new(
            Name: "Meditacion", Description: "Descripcion", Type: RecordingType.Meditacion,
            FileStream: fileStream1, FileName: "file.mp4");
        AdminAddRecordingCommand command2 = new(
            Name: "Meditacion", Description: "Descripcion", Type: RecordingType.Meditacion,
            FileStream: fileStream2, FileName: "file.mp4");

        CurrentUserServiceMock.Setup(x => x.UserId).Returns("admin-user-id");

        StoragePortMock
            .Setup(x => x.UploadAsync(It.IsAny<string>(), It.IsAny<Stream>(), It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success("key"));

        RegistryPortMock
            .Setup(x => x.SaveAsync(It.IsAny<RecordingEntity>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync((RecordingEntity entity, CancellationToken _) => Result.Success(entity.Id));

        // When: the handler processes both commands
        Result<string> result1 = await Handler.Handle(command1, CancellationToken.None);
        Result<string> result2 = await Handler.Handle(command2, CancellationToken.None);

        // Then: each execution should produce a different ID
        Assert.That(result1.IsSuccess, Is.True,
            $"Expected first result to be success but got error: '{(result1.IsSuccess ? "N/A" : result1.Error)}'");
        Assert.That(result2.IsSuccess, Is.True,
            $"Expected second result to be success but got error: '{(result2.IsSuccess ? "N/A" : result2.Error)}'");;
        Assert.That(result1.Value, Is.Not.EqualTo(result2.Value),
            $"Expected unique IDs per execution but both returned: '{result1.Value}'");
    }

    #endregion
}

using FluentValidation;
using FluentValidation.Results;
using Microsoft.Extensions.Logging;
using Moq;
using NUnit.Framework;
using VibraHeka.Application.Recordings.Queries.GetRecordingDownloadUrl;
using VibraHeka.Domain.Recordings.Entities;
using VibraHeka.Domain.Recordings.Enums;
using VibraHeka.Domain.Recordings.Ports.Out;

namespace VibraHeka.Application.UnitTests.Recordings.Queries.GetRecordingDownloadUrl;

public abstract class GenericGetRecordingDownloadUrlTest
{
    protected Mock<IRecordingRegistryPort> RegistryPortMock = default!;
    protected Mock<IRecordingStoragePort> StoragePortMock = default!;
    protected Mock<IValidator<GetRecordingDownloadUrlQuery>> ValidatorMock = default!;
    protected Mock<ILogger<GetRecordingDownloadUrlQueryHandler>> LoggerMock = default!;
    protected GetRecordingDownloadUrlQueryHandler Handler = default!;

    [SetUp]
    public virtual void SetUp()
    {
        RegistryPortMock = new Mock<IRecordingRegistryPort>();
        StoragePortMock = new Mock<IRecordingStoragePort>();
        ValidatorMock = new Mock<IValidator<GetRecordingDownloadUrlQuery>>();
        LoggerMock = new Mock<ILogger<GetRecordingDownloadUrlQueryHandler>>();
        Handler = new GetRecordingDownloadUrlQueryHandler(
            RegistryPortMock.Object,
            StoragePortMock.Object,
            ValidatorMock.Object,
            LoggerMock.Object);
    }

    protected static GetRecordingDownloadUrlQuery BuildValidQuery() =>
        new(Guid.NewGuid().ToString());

    protected static GetRecordingDownloadUrlQuery BuildValidQuery(string recordingId) =>
        new(recordingId);

    protected static ValidationResult ValidValidationResult() => new();

    protected static ValidationResult InvalidValidationResult(string errorMessage) =>
        new(new List<ValidationFailure>
        {
            new ValidationFailure(nameof(GetRecordingDownloadUrlQuery.RecordingId), errorMessage)
        });

    protected static RecordingEntity BuildRecordingEntity(string recordingId, string storageKey) =>
        new()
        {
            Id = recordingId,
            Name = "Meditacion matutina",
            Description = "Una sesion de meditacion para empezar el dia",
            Type = RecordingType.Meditacion,
            StorageKey = storageKey,
            Created = DateTimeOffset.UtcNow,
            CreatedBy = "admin-user-id"
        };
}

using System.ComponentModel;
using CSharpFunctionalExtensions;
using Microsoft.Extensions.Logging;
using Moq;
using NUnit.Framework;
using VibraHeka.Application.Recordings.Queries.GetRecordingDownloadUrl;
using VibraHeka.Domain.Recordings.Errors;

namespace VibraHeka.Application.UnitTests.Recordings.Queries.GetRecordingDownloadUrl;

[TestFixture]
[NUnit.Framework.Category("Unit")]
public sealed class GetRecordingDownloadUrlQueryHandlerTest : GenericGetRecordingDownloadUrlTest
{
    #region Happy Path Tests

    [Test]
    [DisplayName("Should return success with download URL when recording exists and storage succeeds")]
    public async Task ShouldReturnSuccessWithDownloadUrlWhenRecordingExistsAndStorageSucceeds()
    {
        // Given: a valid query, registry returns recording, storage returns pre-signed URL
        string recordingId = Guid.NewGuid().ToString();
        string storageKey = $"https://bucket.s3.us-east-1.amazonaws.com/{recordingId}/meditacion.mp4";
        string downloadUrl = "https://pre-signed-url.example.com/download?token=abc";

        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(ValidValidationResult());

        RegistryPortMock
            .Setup(r => r.GetByIdAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success(BuildRecordingEntity(recordingId, storageKey)));

        StoragePortMock
            .Setup(s => s.GetDownloadUrlAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success(downloadUrl));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: result should be success with the expected download URL
        Assert.That(result.IsSuccess, Is.True,
            $"Expected success but got failure with error: '{(result.IsSuccess ? "N/A" : result.Error)}'");
        Assert.That(result.Value.DownloadUrl, Is.EqualTo(downloadUrl),
            $"Expected DownloadUrl '{downloadUrl}' but got '{result.Value.DownloadUrl}'");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once with the correct query");

        RegistryPortMock.Verify(
            r => r.GetByIdAsync(
                It.Is<string>(id => id == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetByIdAsync to be called exactly once with the correct recording ID");

        StoragePortMock.Verify(
            s => s.GetDownloadUrlAsync(
                It.Is<string>(key => key == storageKey),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetDownloadUrlAsync to be called exactly once with the recording's storage key");

        ValidatorMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
        StoragePortMock.VerifyNoOtherCalls();
    }

    #endregion

    #region Validation Failure Tests

    [Test]
    [DisplayName("Should return failure and not call ports when validation fails")]
    public async Task ShouldReturnFailureAndNotCallPortsWhenValidationFails()
    {
        // Given: validator returns an invalid result for a bad recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery("not-a-guid");

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(InvalidValidationResult(RecordingErrors.InvalidRecordingId));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: result should be failure and neither port should be called (short-circuit)
        Assert.That(result.IsFailure, Is.True,
            $"Expected failure when validation fails, but got success with value: '{(result.IsSuccess ? result.Value.DownloadUrl : "N/A")}'");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == query.RecordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once");

        RegistryPortMock.Verify(
            r => r.GetByIdAsync(
                It.Is<string>(_ => true),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Never,
            "Expected GetByIdAsync to never be called when validation fails");

        StoragePortMock.Verify(
            s => s.GetDownloadUrlAsync(
                It.Is<string>(_ => true),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Never,
            "Expected GetDownloadUrlAsync to never be called when validation fails");

        ValidatorMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
        StoragePortMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should log warning when validation fails")]
    public async Task ShouldLogWarningWhenValidationFails()
    {
        // Given: validator returns an invalid result
        GetRecordingDownloadUrlQuery query = BuildValidQuery("not-a-guid");

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(InvalidValidationResult(RecordingErrors.InvalidRecordingId));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: a Warning log should be emitted for the validation failure
        Assert.That(result.IsFailure, Is.True,
            "Expected failure when validation fails");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == query.RecordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once");

        LoggerMock.Verify(
            x => x.Log(
                LogLevel.Warning,
                It.IsAny<EventId>(),
                It.Is<It.IsAnyType>((v, _) => v.ToString()!.Contains("Validation failed")),
                null,
                It.IsAny<Func<It.IsAnyType, Exception?, string>>()),
            Times.Once,
            "Expected a Warning log containing 'Validation failed' when validation fails");
    }

    #endregion

    #region Railway Pattern Tests

    [Test]
    [DisplayName("Should return REC-001 failure and not call StoragePort when recording is not found")]
    public async Task ShouldReturnREC001FailureAndNotCallStoragePortWhenRecordingNotFound()
    {
        // Given: validation passes but registry returns REC-001 (not found)
        string recordingId = Guid.NewGuid().ToString();
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(ValidValidationResult());

        RegistryPortMock
            .Setup(r => r.GetByIdAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Failure<Domain.Recordings.Entities.RecordingEntity>(RecordingErrors.NotFound));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: result should be failure with REC-001 and StoragePort should never be called (Railway)
        Assert.That(result.IsFailure, Is.True,
            "Expected failure when recording not found, but got success");
        Assert.That(result.Error, Is.EqualTo(RecordingErrors.NotFound),
            $"Expected error '{RecordingErrors.NotFound}' but got '{result.Error}'");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once");

        RegistryPortMock.Verify(
            r => r.GetByIdAsync(
                It.Is<string>(id => id == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetByIdAsync to be called once");

        StoragePortMock.Verify(
            s => s.GetDownloadUrlAsync(
                It.Is<string>(_ => true),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Never,
            "Expected GetDownloadUrlAsync to never be called when registry returns not found (Railway)");

        ValidatorMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
        StoragePortMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should not call StoragePort when RegistryPort fails with generic error (Railway)")]
    public async Task ShouldNotCallStoragePortWhenRegistryPortFailsWithGenericError()
    {
        // Given: validation passes but registry returns a generic persistence error
        string recordingId = Guid.NewGuid().ToString();
        string genericError = "GPE-999";
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(ValidValidationResult());

        RegistryPortMock
            .Setup(r => r.GetByIdAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Failure<Domain.Recordings.Entities.RecordingEntity>(genericError));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: result should be failure with the original error (not REC-001) and StoragePort never called
        Assert.That(result.IsFailure, Is.True,
            "Expected failure when RegistryPort fails");
        Assert.That(result.Error, Is.EqualTo(genericError),
            $"Expected error '{genericError}' but got '{result.Error}'");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once");

        RegistryPortMock.Verify(
            r => r.GetByIdAsync(
                It.Is<string>(id => id == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetByIdAsync to be called once even when it returns failure");

        StoragePortMock.Verify(
            s => s.GetDownloadUrlAsync(
                It.Is<string>(_ => true),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Never,
            "Expected GetDownloadUrlAsync to never be called when RegistryPort fails (Railway pattern)");

        ValidatorMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
        StoragePortMock.VerifyNoOtherCalls();
    }

    [Test]
    [DisplayName("Should return failure when StoragePort fails after registry succeeds")]
    public async Task ShouldReturnFailureWhenStoragePortFailsAfterRegistrySucceeds()
    {
        // Given: validation and registry succeed, but storage fails
        string recordingId = Guid.NewGuid().ToString();
        string storageKey = $"recordings/{recordingId}/taller.mp4";
        string storageError = "S3_PRESIGN_FAILED";
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        ValidatorMock
            .Setup(v => v.ValidateAsync(It.IsAny<GetRecordingDownloadUrlQuery>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(ValidValidationResult());

        RegistryPortMock
            .Setup(r => r.GetByIdAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Success(BuildRecordingEntity(recordingId, storageKey)));

        StoragePortMock
            .Setup(s => s.GetDownloadUrlAsync(It.IsAny<string>(), It.IsAny<CancellationToken>()))
            .ReturnsAsync(Result.Failure<string>(storageError));

        // When: the handler processes the query
        Result<RecordingDownloadUrlDto> result = await Handler.Handle(query, CancellationToken.None);

        // Then: result should be failure with the storage error propagated
        Assert.That(result.IsFailure, Is.True,
            "Expected failure when storage fails, but got success");
        Assert.That(result.Error, Is.EqualTo(storageError),
            $"Expected error '{storageError}' but got '{result.Error}'");

        ValidatorMock.Verify(
            v => v.ValidateAsync(
                It.Is<GetRecordingDownloadUrlQuery>(q => q.RecordingId == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected ValidateAsync to be called exactly once");

        RegistryPortMock.Verify(
            r => r.GetByIdAsync(
                It.Is<string>(id => id == recordingId),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetByIdAsync to be called exactly once");

        StoragePortMock.Verify(
            s => s.GetDownloadUrlAsync(
                It.Is<string>(key => key == storageKey),
                It.Is<CancellationToken>(ct => ct == CancellationToken.None)),
            Times.Once,
            "Expected GetDownloadUrlAsync to be called once with the recording's storage key even on failure");

        ValidatorMock.VerifyNoOtherCalls();
        RegistryPortMock.VerifyNoOtherCalls();
        StoragePortMock.VerifyNoOtherCalls();
    }

    #endregion
}

using System.ComponentModel;
using FluentValidation.Results;
using FluentValidation.TestHelper;
using NUnit.Framework;
using VibraHeka.Application.Recordings.Queries.GetRecordingDownloadUrl;
using VibraHeka.Domain.Recordings.Errors;

namespace VibraHeka.Application.UnitTests.Recordings.Queries.GetRecordingDownloadUrl;

[TestFixture]
[NUnit.Framework.Category("Unit")]
public sealed class GetRecordingDownloadUrlQueryValidatorTest : GenericGetRecordingDownloadUrlTest
{
    private GetRecordingDownloadUrlQueryValidator RealValidator = default!;

    [SetUp]
    public override void SetUp()
    {
        base.SetUp();
        RealValidator = new GetRecordingDownloadUrlQueryValidator();
    }

    #region Empty / Whitespace RecordingId Tests

    [TestCase("", TestName = "Empty string")]
    [TestCase("   ", TestName = "Whitespace only")]
    [DisplayName("Should fail validation when RecordingId is empty or whitespace")]
    public void ShouldFailValidationWhenRecordingIdIsEmptyOrWhitespace(string recordingId)
    {
        // Given: a query with an empty or whitespace recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have a validation error for RecordingId with InvalidRecordingId error code
        result.ShouldHaveValidationErrorFor(x => x.RecordingId)
            .WithErrorMessage(RecordingErrors.InvalidRecordingId);
    }

    #endregion

    #region Invalid GUID Format Tests

    [TestCase("not-a-guid", TestName = "Non-GUID string")]
    [TestCase("12345", TestName = "Numeric string")]
    [TestCase("abc-def-ghi-jkl", TestName = "Hyphenated non-GUID string")]
    [DisplayName("Should fail validation when RecordingId is not a valid GUID format")]
    public void ShouldFailValidationWhenRecordingIdIsNotValidGuid(string recordingId)
    {
        // Given: a query with an invalid (non-GUID format) recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(recordingId);

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have a validation error for RecordingId with InvalidRecordingId error code
        result.ShouldHaveValidationErrorFor(x => x.RecordingId)
            .WithErrorMessage(RecordingErrors.InvalidRecordingId);
    }

    #endregion

    #region Happy Path Tests

    [Test]
    [DisplayName("Should pass validation when RecordingId is a valid GUID string")]
    public void ShouldPassValidationWhenRecordingIdIsValidGuid()
    {
        // Given: a query with a valid GUID recording ID
        GetRecordingDownloadUrlQuery query = BuildValidQuery(Guid.NewGuid().ToString());

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should not have any validation error for RecordingId
        result.ShouldNotHaveValidationErrorFor(x => x.RecordingId);
    }

    [Test]
    [DisplayName("Should pass validation when all fields are valid")]
    public void ShouldPassValidationWhenAllFieldsAreValid()
    {
        // Given: a query with all fields valid (generated by BuildValidQuery)
        GetRecordingDownloadUrlQuery query = BuildValidQuery();

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should not have any validation errors
        result.ShouldNotHaveAnyValidationErrors();
    }

    #endregion

    #region CascadeMode Tests

    [Test]
    [DisplayName("Should report exactly one error per field when CascadeMode is Stop")]
    public void ShouldReportExactlyOneErrorForRecordingIdWhenCascadeModeIsStop()
    {
        // Given: a query with an empty recording ID (triggers both NotEmpty and Must rules)
        GetRecordingDownloadUrlQuery query = BuildValidQuery("");

        // When: validating the query
        TestValidationResult<GetRecordingDownloadUrlQuery> result = RealValidator.TestValidate(query);

        // Then: should have exactly 1 error for RecordingId (CascadeMode.Stop stops after first failure)
        IEnumerable<ValidationFailure> idErrors = result.Errors
            .Where(e => e.PropertyName == nameof(GetRecordingDownloadUrlQuery.RecordingId))
            .ToList();

        Assert.That(idErrors.Count(), Is.EqualTo(1),
            $"Expected exactly 1 error for RecordingId with CascadeMode.Stop, but got {idErrors.Count()}");
        Assert.That(idErrors.First().ErrorMessage, Is.EqualTo(RecordingErrors.InvalidRecordingId),
            $"Expected error '{RecordingErrors.InvalidRecordingId}' but got: '{idErrors.First().ErrorMessage}'");
    }

    #endregion
}

using System.ComponentModel;
using NUnit.Framework;
